        return number.toLocaleString();
    };

    return [w.config.series[seriesIndex].name, formatNumber(value) + " " + w.config.series[seriesIndex].itemUnitName];
}

tooltip.custom:
function({ series, seriesIndex, dataPointIndex, w }) {       
    const formatDate = (timestamp) => {
        const date = new Date(timestamp);
        const options = {
            year: '2-digit',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: false
        };
        return date.toLocaleString('en-US', options).replace(',', '');
    };

    const formatNumber = (number) => {
        return number.toLocaleString();
    };

    return ( 
        "<div style='padding: 5px'>" +
            "<b>Lot Name:</b> " + w.config.series[seriesIndex].name + "<p>" +
            "<b>Qty:</b> " + formatNumber(series[seriesIndex][dataPointIndex]) +" " +w.config.series[seriesIndex].itemUnitName+ "<p>" +
            "<b>State:</b> " + w.config.series[seriesIndex].lotStateName + "<p>" +
            "<b>Reason:</b> " + w.config.series[seriesIndex].lotStateReasonName + "<p>" +
            "<b>Item:</b> " + w.config.series[seriesIndex].itemName + "<p>" +
            "<b>Timestamp:</b> " + formatDate(w.config.series[seriesIndex].tStamp) + "<p>" +
        "</div>"
    );
}

